ALTER TABLE order_logistics_cost
    ADD COLUMN TRANSPORT_PURPOSE_CODE VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '运输用途编码：采购运输、仓间调拨、销售配送、非销售配送、其他运输',
    ADD COLUMN DELIVERY_MODE_CODE VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '承运方式编码：SELF自营、THIRD_PARTY第三方',
    ADD COLUMN CARRIER_CODE VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '物流公司编码，名称通过现有字典或档案查询，第三方承运时必填',
    ADD COLUMN TRACKING_NO VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '运单号，第三方无单号时在业务JSON填写原因',
    ADD COLUMN COST_MONTH VARCHAR(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '物流费用归属月份，格式YYYY-MM，新版确认时必填',
    ADD COLUMN ORIGIN_BIZ_KEY VARCHAR(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自动生成业务唯一键，例如ERP:PROCUREMENT_ORDER:采购单编码:FREIGHT，手工费用为空',
    ADD UNIQUE KEY UK_LOGISTICS_ORIGIN_BIZ (TENANT_ID, ORIGIN_BIZ_KEY),
    ADD KEY IX_LOGISTICS_MONTH_STATUS (TENANT_ID, COST_MONTH, STATUS_CODE),
    ADD KEY IX_LOGISTICS_CARRIER_TRACKING (TENANT_ID, CARRIER_CODE, TRACKING_NO);
